import { createHash } from 'node:crypto'

import { sendLinePush } from '../../line/client'
import type { ChannelSendResult, NotificationChannel, OutboundMessage } from '../types'

/**
 * LINE's `X-Line-Retry-Key` must be "a UUID in hexadecimal format," but per
 * LINE's own docs it can be "generated by any method" — it only needs to be
 * STABLE for the same logical request across retries, and different across
 * different requests. dedupeKey already uniquely identifies one notification
 * row, so hashing it deterministically into the UUID shape (rather than
 * generating a fresh random UUID per send attempt, which would defeat the
 * whole point) gives every retry of the same row the same retry key.
 */
function deriveLineRetryKey(dedupeKey: string): string {
  const hex = createHash('sha256').update(dedupeKey).digest('hex').slice(0, 32)
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20, 32)}`
}

/**
 * The LINE side of the notification dispatcher. Always sends via push — see
 * docs/STEP2-LINE-CATALOGUE.md Part 0.4 and the STEP 2 Part 3 report's reply-
 * vs-push finding: none of this dispatcher's call sites (booking
 * confirmation, day-before reminder, cancellation) fire from inside an
 * active LINE webhook event, so no replyToken is ever available to them.
 * `html`/`subject` on OutboundMessage are meaningless here and go unused,
 * same as EmailResendChannel ignoring fields it doesn't need (see types.ts).
 */
export class LineMessagingChannel implements NotificationChannel {
  readonly id = 'line' as const

  /**
   * Takes a token GETTER, not a resolved token — read lazily at send time so
   * a missing/misconfigured LINE_CHANNEL_ACCESS_TOKEN fails inside
   * attemptSend's existing retry/backoff handling, not at dispatcher
   * construction (mirrors lib/line.ts's getLineAccessToken() rationale).
   */
  constructor(private readonly getAccessToken: () => string) {}

  async send(message: OutboundMessage): Promise<ChannelSendResult> {
    if (!message.text) {
      throw new Error('LineMessagingChannel: message has no text content to send')
    }
    const retryKey = message.dedupeKey ? deriveLineRetryKey(message.dedupeKey) : undefined
    const result = await sendLinePush(
      message.to,
      [{ type: 'text', text: message.text }],
      this.getAccessToken(),
      retryKey,
    )
    return { providerMessageId: result.messageId }
  }
}
